const cfg = { ...$json };
const zone = cfg.timezone || 'America/Los_Angeles';
const lagDays = Number(cfg.sync_lag_days ?? 1);
const target = $now.setZone(zone).minus({ days: lagDays });
return [{
  json: {
    ...cfg,
    target_date: target.toFormat('yyyy-MM-dd'),
    target_year: Number(target.toFormat('yyyy')),
    target_month: Number(target.toFormat('M')),
    target_day: Number(target.toFormat('d')),
    updated_at: new Date().toISOString()
  }
}];

const cfg = $('Calculate Sync Date').first().json;
const accounts = $json.accounts || [];
if (!accounts.length) {
  return [{ json: { ...cfg, error: 'No Google Business Profile accounts returned for this OAuth user.' } }];
}
return accounts.map((account) => ({
  json: {
    ...cfg,
    account_name: account.name,
    account_id: String(account.name || '').replace('accounts/', ''),
    account_display_name: account.accountName || account.name,
    locations_url: 'https://mybusinessbusinessinformation.googleapis.com/v1/' + account.name + '/locations?readMask=name,title,storeCode,metadata,phoneNumbers,websiteUri&filter=openInfo.status=OPEN'
  }
}));

const accountItems = $('Build Location Requests').all();
const locationItems = $input.all();
const cfg = $('Calculate Sync Date').first().json;
const needle = String(cfg.location_match_text || cfg.client_name || '').toLowerCase();
const candidates = [];
for (let i = 0; i < locationItems.length; i++) {
  const source = accountItems[i]?.json || {};
  const locations = locationItems[i].json.locations || [];
  for (const location of locations) {
    const title = String(location.title || '').toLowerCase();
    const storeCode = String(location.storeCode || '').toLowerCase();
    if (!needle || title.includes(needle) || storeCode.includes(needle)) {
      candidates.push({ source, location });
    }
  }
}
if (!candidates.length) {
  return [{ json: { ...cfg, error: 'No GBP location matched ' + needle + '. Confirm the OAuth user has manager access to Press Burger.' } }];
}
const { source, location } = candidates[0];
const locationName = location.name;
const locationId = String(locationName || '').replace('locations/', '');
return [{
  json: {
    ...cfg,
    account_name: source.account_name,
    account_id: source.account_id,
    account_display_name: source.account_display_name,
    location_name: locationName,
    location_id: locationId,
    business_profile_name: location.title || cfg.client_name,
    reviews_url: 'https://mybusiness.googleapis.com/v4/' + source.account_name + '/' + locationName + '/reviews?pageSize=50&orderBy=updateTime%20desc',
    performance_url: 'https://businessprofileperformance.googleapis.com/v1/' + locationName + ':fetchMultiDailyMetricsTimeSeries'
      + '?dailyMetrics=BUSINESS_IMPRESSIONS_DESKTOP_MAPS'
      + '&dailyMetrics=BUSINESS_IMPRESSIONS_DESKTOP_SEARCH'
      + '&dailyMetrics=BUSINESS_IMPRESSIONS_MOBILE_MAPS'
      + '&dailyMetrics=BUSINESS_IMPRESSIONS_MOBILE_SEARCH'
      + '&dailyMetrics=BUSINESS_DIRECTION_REQUESTS'
      + '&dailyMetrics=CALL_CLICKS'
      + '&dailyMetrics=WEBSITE_CLICKS'
      + '&dailyMetrics=BUSINESS_FOOD_ORDERS'
      + '&dailyRange.start_date.year=' + cfg.target_year
      + '&dailyRange.start_date.month=' + cfg.target_month
      + '&dailyRange.start_date.day=' + cfg.target_day
      + '&dailyRange.end_date.year=' + cfg.target_year
      + '&dailyRange.end_date.month=' + cfg.target_month
      + '&dailyRange.end_date.day=' + cfg.target_day
  }
}];

const ctx = $('Select Press Burger Location').first().json;
if (ctx.error) return [{ json: { ...ctx, ok: false, errors: [ctx.error] } }];
const reviewsResponse = $('GBP - Fetch Reviews').first().json || {};
const performanceResponse = $('GBP - Fetch Performance').first().json || {};
const targetDate = ctx.target_date;
const reviews = reviewsResponse.reviews || [];
const ratingMap = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
function ratingValue(value) {
  if (typeof value === 'number') return value;
  return ratingMap[String(value || '').toUpperCase()] || null;
}
function dateOnly(value) {
  return value ? String(value).slice(0, 10) : null;
}
const targetReviews = reviews.filter((review) => dateOnly(review.createTime || review.updateTime) === targetDate);
const fiveStarReviews = targetReviews.filter((review) => ratingValue(review.starRating) === 5).length;
const latestReview = reviews[0] || null;
function metricValue(metric) {
  const groups = performanceResponse.multiDailyMetricTimeSeries || [];
  let total = 0;
  let found = false;
  for (const group of groups) {
    const seriesList = group.dailyMetricTimeSeries || [];
    for (const series of seriesList) {
      if (series.dailyMetric !== metric) continue;
      const datedValues = series.timeSeries?.datedValues || series.timeSeries?.dated_values || [];
      for (const point of datedValues) {
        const pointDate = point.date ? [point.date.year, String(point.date.month).padStart(2, '0'), String(point.date.day).padStart(2, '0')].join('-') : null;
        if (pointDate && pointDate !== targetDate) continue;
        const value = Number(point.value || 0);
        if (Number.isFinite(value)) {
          total += value;
          found = true;
        }
      }
    }
  }
  return found ? total : null;
}
const desktopMaps = metricValue('BUSINESS_IMPRESSIONS_DESKTOP_MAPS');
const desktopSearch = metricValue('BUSINESS_IMPRESSIONS_DESKTOP_SEARCH');
const mobileMaps = metricValue('BUSINESS_IMPRESSIONS_MOBILE_MAPS');
const mobileSearch = metricValue('BUSINESS_IMPRESSIONS_MOBILE_SEARCH');
const searchViews = [desktopSearch, mobileSearch].some((v) => v !== null) ? Number(desktopSearch || 0) + Number(mobileSearch || 0) : null;
const mapViews = [desktopMaps, mobileMaps].some((v) => v !== null) ? Number(desktopMaps || 0) + Number(mobileMaps || 0) : null;
const profileViews = [searchViews, mapViews].some((v) => v !== null) ? Number(searchViews || 0) + Number(mapViews || 0) : null;
const row = {
  client_id: ctx.client_id,
  date: targetDate,
  business_profile_name: ctx.business_profile_name,
  source: 'google_business_profile_api',
  status: 'live',
  access_blocker: null,
  new_reviews: targetReviews.length,
  five_star_reviews: fiveStarReviews,
  total_reviews: reviewsResponse.totalReviewCount ?? null,
  average_rating: reviewsResponse.averageRating ?? null,
  profile_views: profileViews,
  search_views: searchViews,
  map_views: mapViews,
  website_clicks: metricValue('WEBSITE_CLICKS'),
  phone_calls: metricValue('CALL_CLICKS'),
  direction_requests: metricValue('BUSINESS_DIRECTION_REQUESTS'),
  food_orders: metricValue('BUSINESS_FOOD_ORDERS'),
  latest_review_rating: latestReview ? ratingValue(latestReview.starRating) : null,
  latest_review_author: latestReview?.reviewer?.displayName || null,
  latest_review_text: latestReview?.comment || null,
  latest_review_at: latestReview?.updateTime || latestReview?.createTime || null,
  notes: 'Synced from Google Business Profile API by n8n.',
  raw_payload: {
    account_name: ctx.account_name,
    location_name: ctx.location_name,
    location_id: ctx.location_id,
    reviews_sample_count: reviews.length,
    performance: performanceResponse
  },
  updated_at: ctx.updated_at
};
return [{ json: { ...ctx, ok: true, row } }];

const data = $('Normalize GBP Activity').first().json;
const upsert = $('Supabase Upsert - gbp_activity').first().json;
return [{ json: {
  ok: true,
  client_name: data.client_name,
  date: data.target_date,
  location: data.business_profile_name,
  row: data.row,
  supabase_response: upsert,
  message: 'GBP activity sync completed for ' + data.client_name + ' on ' + data.target_date
} }];
